// ─────────────────────────────────────────────────────────────── salts
const SaltsMode = ({
	frame, beats, id, acidSolubility, saltSolubility, foldLabel, reviewedMedicine,
}: {frame: number; beats: number[]; id: string; acidSolubility: number; saltSolubility: number; foldLabel: string; reviewedMedicine: boolean}) => {
	const [tAcid, tSalt, tFold, tNote, tPanel, tRise, tOpp, tLowest] = beats;
	const PCY = 424;
	const scale = 240 / saltSolubility; // px per g/L
	const hAcid = (reviewedMedicine ? acidSolubility * scale : Math.max(2, acidSolubility * scale)) * ease(ramp(frame, tAcid, 24));
	const hSalt = saltSolubility * scale * ease(ramp(frame, tSalt, 40));
	const AX = 118, SX = 272, BWd = 74;
	const enter = ramp(frame, 0, 18);

	// Right panel: Ka axis (up = larger) and pKa axis (down = larger).
	const KX = 520, PX = 630, TOPY = 146, BOTY = 380;
	const rise = ease(ramp(frame, tRise, 80));
	const sway = frame >= tOpp ? Math.sin(((frame - tOpp) / 70) * Math.PI) * 0.35 * Math.min(1, (frame - tOpp) / 30) : 0;
	const lvl = Math.max(0, Math.min(1, 0.15 + 0.75 * rise - (frame >= tOpp ? Math.abs(sway) : 0)));
	const SYl = BOTY - 20 - lvl * (BOTY - TOPY - 40);
	const panelIn = ramp(frame, tPanel, 16);

	return (
		<g>
			{/* Left: solubility to scale */}
			<g opacity={enter}>
				<text x={195} y={40} textAnchor="middle" fill={TOK.ink} fontSize={23} fontWeight={800}>{reviewedMedicine ? 'Illustrative data only' : 'Aspirin in water'}</text>
			</g>
			<g opacity={ramp(frame, tNote, 16)}>
				<text x={195} y={70} textAnchor="middle" fill={TOK.inkDim} fontSize={16} fontWeight={700}>{reviewedMedicine ? 'Not measured aspirin solubilities' : 'Salt forms (e.g. morphine sulfate):'}</text>
				<text x={195} y={92} textAnchor="middle" fill={TOK.ink} fontSize={16} fontWeight={800}>{reviewedMedicine ? 'Salt formation is not a universal fix' : 'fix solubility, not membrane crossing'}</text>
			</g>
			<DioramaPlinth id={id} cx={195} cy={PCY} rx={160}>
				<g opacity={enter}>
					{/* baseline scale tick for 500 g/L */}
					<line x1={AX - BWd / 2 - 8} y1={PCY - saltSolubility * scale} x2={SX + BWd / 2 + 14} y2={PCY - saltSolubility * scale} stroke={TOK.inkMute} strokeWidth={1.5} strokeDasharray="5 6" opacity={ramp(frame, tSalt + 30, 14)} />
					<rect x={AX - BWd / 2} y={PCY - hAcid} width={BWd} height={hAcid} fill={HA_COLOR} stroke={shade(HA_COLOR, -0.3)} strokeWidth={1} />
					<ellipse cx={AX} cy={PCY - hAcid} rx={BWd / 2} ry={7} fill={shade(HA_COLOR, 0.15)} stroke={shade(HA_COLOR, -0.3)} strokeWidth={1} opacity={ramp(frame, tAcid, 10)} />
					<rect x={SX - BWd / 2} y={PCY - hSalt} width={BWd} height={hSalt} fill={A_COLOR} stroke={shade(A_COLOR, -0.3)} strokeWidth={1} />
					<rect x={SX - BWd / 2 + 8} y={PCY - hSalt + 8} width={12} height={Math.max(0, hSalt - 16)} rx={5} fill="#ffffff" opacity={0.28} />
					<ellipse cx={SX} cy={PCY - hSalt} rx={BWd / 2} ry={7} fill={shade(A_COLOR, 0.15)} stroke={shade(A_COLOR, -0.3)} strokeWidth={1} opacity={ramp(frame, tSalt, 10)} />
					<ellipse cx={AX} cy={PCY} rx={BWd / 2} ry={7} fill="none" stroke={TOK.inkMute} strokeWidth={1.5} strokeDasharray="4 4" />
				</g>
				<g opacity={ramp(frame, tAcid + 10, 14)}>
					<text x={AX} y={PCY - hAcid - 16} textAnchor="middle" fill={INK_HA} fontSize={19} fontWeight={800}>{reviewedMedicine ? `${acidSolubility} g/L` : 'about 3 g/L'}</text>
					<text x={AX} y={PCY + 38} textAnchor="middle" fill={TOK.ink} fontSize={17} fontWeight={800}>free acid</text>
				</g>
				<g opacity={ramp(frame, tSalt + 36, 14)}>
					<text x={SX} y={PCY - saltSolubility * scale - 16} textAnchor="middle" fill={INK_A} fontSize={19} fontWeight={800}>{reviewedMedicine ? `${saltSolubility} g/L` : 'over 500 g/L'}</text>
				</g>
				<g opacity={ramp(frame, tSalt, 14)}>
					<text x={SX} y={PCY + 38} textAnchor="middle" fill={TOK.ink} fontSize={17} fontWeight={800}>{reviewedMedicine ? 'salt form' : 'sodium salt'}</text>
				</g>
			</DioramaPlinth>
			<g opacity={ramp(frame, tFold, 16)}>
				<text x={AX + 8} y={262} textAnchor="middle" fill={TOK.ink} fontSize={24} fontWeight={800}>{reviewedMedicine ? `${illustrativeSolubilityRatio(acidSolubility,saltSolubility).toFixed(1)}-fold` : foldLabel}</text>
				<text x={AX + 8} y={288} textAnchor="middle" fill={TOK.inkDim} fontSize={18} fontWeight={700}>jump</text>
				<Arrow x1={AX + 8} y1={352} x2={AX + 8} y2={306} color={TOK.inkDim} width={3} head={12} progress={ramp(frame, tFold, 20)} />
			</g>

			<line x1={395} y1={24} x2={395} y2={506} stroke={TOK.rule} strokeWidth={2} opacity={panelIn} />

			{/* Right: Ka vs pKa */}
			<g opacity={panelIn}>
				<text x={575} y={40} textAnchor="middle" fill={TOK.ink} fontSize={23} fontWeight={800}>{reviewedMedicine ? 'Same solvent and temperature' : 'Ranking acid strength'}</text>
				<text x={575} y={118} textAnchor="middle" fill={TOK.ink} fontSize={19} fontWeight={800}>stronger acid</text>
				<text x={575} y={414} textAnchor="middle" fill={TOK.inkDim} fontSize={19} fontWeight={700}>weaker acid</text>
				<Arrow x1={KX} y1={BOTY} x2={KX} y2={TOPY} color={TOK.ink} width={3.5} head={14} />
				<Arrow x1={PX} y1={TOPY} x2={PX} y2={BOTY} color={TOK.ink} width={3.5} head={14} />
				<text x={KX - 14} y={TOPY + 16} textAnchor="end" fill={TOK.ink} fontSize={19} fontWeight={800}>larger Ka</text>
				<text x={PX + 14} y={BOTY - 4} textAnchor="start" fill={TOK.ink} fontSize={19} fontWeight={800}>larger pKa</text>
				<text x={KX - 14} y={268} textAnchor="end" fill={TOK.inkDim} fontSize={22} fontWeight={800}>Ka</text>
				<text x={PX + 14} y={268} textAnchor="start" fill={TOK.inkDim} fontSize={22} fontWeight={800}>pKa</text>
				{/* the acid's level on both scales */}
				<line x1={KX} y1={SYl} x2={PX} y2={SYl} stroke={HA_COLOR} strokeWidth={3} strokeDasharray="6 5" />
				<circle cx={KX} cy={SYl} r={11} fill={`url(#${id}-g-ha)`} stroke={shade(HA_COLOR, -0.3)} />
				<circle cx={PX} cy={SYl} r={11} fill={`url(#${id}-g-ha)`} stroke={shade(HA_COLOR, -0.3)} />
			</g>
			<g opacity={ramp(frame, tOpp, 16)}>
				<text x={575} y={76} textAnchor="middle" fill={TOK.ink} fontSize={22} fontWeight={800}>pKa = −log Ka</text>
				<text x={575} y={444} textAnchor="middle" fill={TOK.inkDim} fontSize={17} fontWeight={700}>Ka and pKa move in opposite directions</text>
			</g>
			<g opacity={ramp(frame, tLowest, 16)}>
				<Pill x={575} y={486} text="Lowest pKa = strongest acid" color={TOK.amber} textColor={TOK.amberInk} size={21} strokeWidth={2 + idlePulse(frame) * 1.5} />
			</g>
		</g>
	);
};

// ─────────────────────────────────────────────────────────────── hocl
const HoclMode = ({frame, beats, id, pKa, lowerPH, higherPH}: {frame: number; beats: number[]; id: string; pKa: number; lowerPH: number; higherPH: number}) => {
	const [tEq1, tEq2, tTag, tHigh, tRise, tVerdict] = beats;
	const N = ROWS.reduce((s, n) => s + n, 0);
	const nLow = N * fracIonised(lowerPH, pKa);
	const nHigh = N * fracIonised(higherPH, pKa);
	const flip = ease(ramp(frame, tRise + 10, 80));

	const Plinth = ({cx, n, seed, enter, pid}: {cx: number; n: number; seed: number; enter: number; pid: string}) => {
		const slots = popSlots(cx, 344, ROWS, 52, 24);
		const ranks = flipRanks(slots.length, seed);
		return (
			<DioramaPlinth id={pid} cx={cx} cy={344} rx={165}>
				{slots.map((s, i) => {
					const st = flipState(n, ranks[i]);
					const x = s.x + idleBob(frame, i + seed * 5, 1.3);
					const y = s.y - 10 + idleBob(frame + 30, i + seed, 1.1);
					const sc = 0.8 + 0.2 * enter;
					return (
						<g key={i} opacity={Math.min(1, enter * 1.4)}>
							{st < 1 && <Molecule id={id} atoms={['O', 'H', 'Cl']} x={x} y={y} r={12} scale={sc} opacity={1 - st} />}
							{st > 0 && (
								<g opacity={st}>
									{/* violet charge halo: the ionised form, same colour as A⁻ in the aspirin scenes */}
									<ellipse cx={x} cy={y - 1} rx={25 * sc} ry={19 * sc} fill={A_COLOR} opacity={0.45} stroke={A_COLOR} strokeWidth={2} strokeOpacity={0.9} />
									<Molecule id={id} atoms={['O', 'Cl']} x={x} y={y} r={12} scale={sc} />
									<text x={x + 13} y={y - 6} fill={TOK.ink} fontSize={21} fontWeight={900}>−</text>
								</g>
							)}
							{st > 0 && st < 1 && <circle cx={x - 8} cy={y - st * 24} r={6} fill={`url(#${id}-atom-H)`} opacity={1 - st} />}
						</g>
					);
				})}
			</DioramaPlinth>
		);
	};

	return (
		<g>
			<g opacity={ramp(frame, 0, 16) * (1 - ramp(frame, tEq1 - 16, 16))}>
				<text x={W / 2} y={60} textAnchor="middle" fill={TOK.ink} fontSize={26} fontWeight={800}>Not how much chlorine,</text>
				<text x={W / 2} y={94} textAnchor="middle" fill={TOK.inkDim} fontSize={26} fontWeight={800}>but which species is present?</text>
			</g>
			<g opacity={ramp(frame, tEq1, 16)}>
				<text x={W / 2} y={40} textAnchor="middle" fill={TOK.ink} fontSize={26} fontWeight={800}>Cl₂ + H₂O → HOCl + HCl</text>
			</g>
			<g opacity={ramp(frame, tEq2, 16)}>
				<text x={W / 2} y={80} textAnchor="middle" fill={TOK.ink} fontSize={26} fontWeight={800}>
					<tspan fill={TOK.amberInk}>HOCl</tspan> ⇌ H⁺ + OCl⁻
				</text>
			</g>

			{/* legend with the key fact */}
			<g opacity={ramp(frame, tTag, 16)}>
				<Molecule id={id} atoms={['O', 'H', 'Cl']} x={58} y={128} r={12} />
				<text x={84} y={137} fill={TOK.ink} fontSize={20} fontWeight={800}>HOCl</text>
				<Pill x={290} y={130} text="more effective disinfectant" color={TOK.amber} textColor={TOK.amberInk} size={17} strokeWidth={2 + idlePulse(frame) * 1.5} />
			</g>
			<g opacity={ramp(frame, tRise, 16)}>
				<ellipse cx={470} cy={127} rx={25} ry={19} fill={A_COLOR} opacity={0.45} stroke={A_COLOR} strokeWidth={2} strokeOpacity={0.9} />
				<Molecule id={id} atoms={['O', 'Cl']} x={470} y={128} r={12} />
				<text x={483} y={122} fill={TOK.ink} fontSize={21} fontWeight={900}>−</text>
				<text x={500} y={137} fill={TOK.ink} fontSize={20} fontWeight={800}>OCl⁻</text>
				<text x={554} y={137} fill={TOK.inkDim} fontSize={17} fontWeight={700}>weaker disinfectant</text>
			</g>

			<g opacity={ramp(frame, tHigh, 16)}>
				<text x={195} y={206} textAnchor="middle" fill={TOK.ink} fontSize={23} fontWeight={800}>Lower pH</text>
				<text x={565} y={206} textAnchor="middle" fill={TOK.ink} fontSize={23} fontWeight={800}>Higher pH</text>
			</g>
			<g opacity={ramp(frame, tRise, 16)}>
				<Arrow x1={300} y1={200} x2={455} y2={200} color={TOK.inkDim} width={3} head={12} progress={ramp(frame, tRise, 24)} />
				<text x={378} y={186} textAnchor="middle" fill={TOK.inkDim} fontSize={16} fontWeight={800}>pH rises</text>
			</g>

			<Plinth cx={195} n={nLow} seed={2} enter={ramp(frame, tEq2, 18)} pid={`${id}l`} />
			<Plinth cx={565} n={nHigh * flip} seed={4} enter={ramp(frame, tHigh, 18)} pid={`${id}h`} />

			<g opacity={ramp(frame, tHigh + 10, 14)}>
				<text x={195} y={462} textAnchor="middle" fill={TOK.ink} fontSize={22} fontWeight={800}>Mostly HOCl</text>
			</g>
			<g opacity={ramp(frame, tRise + 90, 14)}>
				<text x={565} y={462} textAnchor="middle" fill={INK_A} fontSize={22} fontWeight={800}>Mostly OCl⁻</text>
			</g>
			<g opacity={ramp(frame, tVerdict, 16)}>
				<Pill x={195} y={496} text="stronger disinfection" color={TOK.amber} textColor={TOK.amberInk} size={18} strokeWidth={2 + idlePulse(frame) * 1.5} />
				<text x={565} y={502} textAnchor="middle" fill={TOK.inkDim} fontSize={18} fontWeight={700}>weaker disinfection</text>
			</g>
		</g>
	);
};

// ─────────────────────────────────────────────────────────────── root
export const IonisationDiagram = (props: IonisationProps) => {
	const {
		delay = 62,
		mode = 'hh',
		reviewedMedicine = false,
		beats,
		pKa = 3.5,
		stomachRange = [1, 2],
		intestineRange = [6, 7],
		stomachPH = 2,
		intestinePH = 6,
		hoclPKa = 7.5,
		lowerPH = 6.5,
		higherPH = 8.5,
		acidSolubility = 3,
		saltSolubility = 500,
		foldLabel = '160-fold',
	} = props;
	validateReviewedMedicineDiagram({type: 'diorama', kind: 'chem12m8Ionisation', props});
	const frame = useCurrentFrame() - delay;
	useAccent();
	const b = beats && beats.length >= DEFAULT_BEATS[mode].length ? beats : DEFAULT_BEATS[mode];
	const id = `c12m8ion${mode}`;
	const aria: Record<Mode, string> = {
		forms: 'A weak acid HA is in equilibrium with H+ and A-. Unionised HA is less polar and crosses a lipid membrane; ionised A- is more polar, stays in the water and bounces off the membrane.',
		hh: 'Henderson-Hasselbalch: as pH moves from two below the pKa to two above it, a population of weak-acid molecules shifts from HA to A-, with the A- to HA ratio going from 1 to 100 through 1 to 1 up to 100 to 1.',
		compare: `Aspirin, pKa ${pKa}: in the stomach (pH ${stomachRange[0]} to ${stomachRange[1]}) it is mostly unionised HA, which crosses membranes more easily; in the small intestine (pH ${intestineRange[0]} to ${intestineRange[1]}) it is mostly ionised A-, more water-soluble and less membrane-permeable.`,
		salts: `Aspirin free acid dissolves at about ${acidSolubility} g/L and its sodium salt at over ${saltSolubility} g/L, drawn to scale. A larger Ka or a smaller pKa means a stronger acid; the lowest pKa is the strongest acid.`,
		hocl: 'Chlorine and water give HOCl and HCl; HOCl ionises to H+ and OCl-. At lower pH the chlorine is mostly HOCl, the more effective disinfectant; at higher pH it is mostly OCl-, the weaker one.',
	};

	if (reviewedMedicine) {
		aria.forms = 'Simplified passive lipid-diffusion illustration of unionised HA and ionised A-. It does not model every transport route or predict total absorption.';
		aria.hh = 'Ideal dilute single-site weak-acid equilibrium. The ratio is calculated; displayed particle counts are rounded and do not measure absorption.';
		aria.compare = `Ideal weak-acid model with pKa ${pKa}, sampled at pH ${stomachPH} and ${intestinePH}. Equilibrium ionisation fractions, not absorption percentages; particle counts are rounded.`;
		aria.salts = `Illustrative free-acid and salt solubilities of ${acidSolubility} and ${saltSolubility} g/L. These are not measured aspirin values or a universal prediction. Compare acid strength in the same solvent and temperature.`;
	}
	return (
		<svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={aria[mode]} style={{width: '100%', fontFamily: FONT_DISPLAY}}>
			<DioramaDefs id={id} elements={['O', 'H', 'Cl']} />
			<GlossDefs id={id} colors={{...ACID_GLOSS, knob: '#6a6a6a'}} />
			{mode === 'forms' && <FormsMode frame={frame} beats={b} id={id} reviewedMedicine={reviewedMedicine} />}
			{mode === 'hh' && <HHMode frame={frame} beats={b} id={id} reviewedMedicine={reviewedMedicine} />}
			{mode === 'compare' && (
				<CompareMode frame={frame} beats={b} id={id} pKa={pKa} stomachRange={stomachRange} intestineRange={intestineRange} stomachPH={stomachPH} intestinePH={intestinePH} reviewedMedicine={reviewedMedicine} />
			)}
			{mode === 'salts' && <SaltsMode frame={frame} beats={b} id={id} acidSolubility={acidSolubility} saltSolubility={saltSolubility} foldLabel={foldLabel} reviewedMedicine={reviewedMedicine} />}
			{mode === 'hocl' && <HoclMode frame={frame} beats={b} id={id} pKa={hoclPKa} lowerPH={lowerPH} higherPH={higherPH} />}
		</svg>
	);
};

9b92ee4d739f55cd99b646c1f9847ea8523be6d9.content:
// Shared pieces for the chem-y12-m6 lane (Acid/Base Reactions). Lane-local on
// purpose (docs/diorama-system.md): `Species`, `Proton`, `solvePH` and
// `phColor` could be promoted into diorama.tsx if other lanes want them.

import type {ReactNode} from 'react';
import {interpolate, spring} from 'remotion';
import {TOK} from '../../../../styles/tokens';
import {ELEMENT_COLORS} from '../../diorama';

export const clamp = {extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const};

/** 0→1 over `len` frames starting at `d`. */
export const fadeAt = (frame: number, d: number, len = 12) => interpolate(frame, [d, d + len], [0, 1], clamp);

/** Springy 0→1 (slight overshoot) starting at `d`. */
export const popAt = (frame: number, fps: number, d: number) =>
	Math.max(0, spring({frame: frame - d, fps, config: {damping: 12, stiffness: 180, mass: 0.7}}));

/** Smooth 0→1 between frames a and b (ease in-out). */
export const ease = (frame: number, a: number, b: number) => {
	const t = interpolate(frame, [a, b], [0, 1], clamp);
	return t * t * (3 - 2 * t);
};

export const shade = (hex: string, amt: number) => {
	const n = parseInt(hex.slice(1), 16);
	const ch = (v: number) => Math.max(0, Math.min(255, Math.round(v + amt * 255)));
	return `#${((1 << 24) | (ch((n >> 16) & 255) << 16) | (ch((n >> 8) & 255) << 8) | ch(n & 255)).toString(16).slice(1)}`;
};

export const mix = (a: string, b: string, t: number) => {
	const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
	const c = (s: number) => Math.round(((pa >> s) & 255) * (1 - t) + ((pb >> s) & 255) * t);
	return `#${((1 << 24) | (c(16) << 16) | (c(8) << 8) | c(0)).toString(16).slice(1)}`;
};

// Species colours. Cores are CPK where a real element names them (O red, N
// blue, C dark grey, S yellow, Cl green, P orange); ions and "the rest of the
// acid" (A⁻) get a neutral slate so they never read as an element.
export const CORE: Record<string, string> = {
	...ELEMENT_COLORS,
	P: '#e08a2c',
	A: '#6b7a8f',
	Ca: '#9aa3a8',
	Mg: '#b9c2bd',
	Al: '#c4c9d0',
	K: '#8e5bd6',
	Ba: '#7fb069',
};
export const coreColor = (el: string) => CORE[el] ?? '#8a8f99';
export const PROTON = '#f7f5ee';
export const BLUE = '#3f6fd8';

/** Glossy radial fills for named colours: fill={`url(#${id}-g-${name})`}. */
export const GlossDefs = ({id, colors}: {id: string; colors: Record<string, string>}) => (
	<defs>
		{Object.entries(colors).map(([name, base]) => (
			<radialGradient key={name} id={`${id}-g-${name}`} cx="38%" cy="32%" r="70%" fx="32%" fy="26%">
				<stop offset="0%" stopColor="#ffffff" />
				<stop offset="22%" stopColor={shade(base, 0.08)} />
				<stop offset="75%" stopColor={base} />
				<stop offset="100%" stopColor={shade(base, -0.28)} />
			</radialGradient>
		))}
	</defs>
);

/** One glossy ball (GlossDefs colour `name`), optional centred label. */
export const Ball = ({
	id, name, x, y, r, label, labelColor = '#ffffff', labelSize, opacity = 1, scale = 1, stroke, strokeWidth,
}: {
	id: string; name: string; x: number; y: number; r: number; label?: string; labelColor?: string; labelSize?: number;
	opacity?: number; scale?: number; stroke?: string; strokeWidth?: number;
}) => (
	<g opacity={opacity} transform={`translate(${x},${y}) scale(${scale})`}>
		<circle r={r} fill={`url(#${id}-g-${name})`} stroke={stroke ?? 'rgba(0,0,0,0.28)'} strokeWidth={strokeWidth ?? 1} />
		{label && (
			<text y={(labelSize ?? r * 0.9) * 0.36} textAnchor="middle" fill={labelColor} fontSize={labelSize ?? r * 0.9} fontWeight={800}>
				{label}
			</text>
		)}
	</g>
);

/** A free proton: small pearly ball with a "+" (GlossDefs must include `proton`). */
export const Proton = ({id, x, y, r = 13, opacity = 1, glow = 0}: {id: string; x: number; y: number; r?: number; opacity?: number; glow?: number}) => (
	<g opacity={opacity}>
		{glow > 0 && <circle cx={x} cy={y} r={r * 1.9} fill={TOK.amber} opacity={0.28 * glow} />}
		<circle cx={x} cy={y} r={r} fill={`url(#${id}-g-proton)`} stroke="rgba(0,0,0,0.3)" strokeWidth={1} />
		<text x={x} y={y + r * 0.42} textAnchor="middle" fill="#333" fontSize={r * 1.2} fontWeight={800}>+</text>
	</g>
);

/** Satellite H positions around a core of radius R (fan across the top). */
export const hSlots = (n: number, R: number, r: number) => {
	const d = R + r * 0.55;
	const out: {dx: number; dy: number}[] = [];
	for (let i = 0; i < n; i++) {
		const a = n === 1 ? -90 : -150 + (120 * i) / (n - 1);
		const rad = (a * Math.PI) / 180;
		out.push({dx: Math.cos(rad) * d, dy: Math.sin(rad) * d});
	}
	return out;
};

/** A rounded tag (pill) with centred text. */
export const Pill = ({
	x, y, text, color, fill = '#ffffff', size = 16, padX = 11, opacity = 1, strokeWidth = 2, textColor,
}: {x: number; y: number; text: string; color: string; fill?: string; size?: number; padX?: number; opacity?: number; strokeWidth?: number; textColor?: string}) => {
	const w = textWidth(text, size) + padX * 2;
	const h = size + 13;
	return (
		<g opacity={opacity}>
			<rect x={x - w / 2} y={y - h / 2} width={w} height={h} rx={h / 2} fill={fill} stroke={color} strokeWidth={strokeWidth} />
			<text x={x} y={y + size * 0.36} textAnchor="middle" fill={textColor ?? color} fontSize={size} fontWeight={800} letterSpacing="0.02em">
				{text}
			</text>
		</g>
	);
};

/** Rough rendered width of bold Inter Tight text (subscripts/superscripts count narrow). */
export const textWidth = (text: string, size: number) => {
	let w = 0;
	for (const ch of text) {
		if (/[₀-₉⁰-⁹⁺⁻]/.test(ch)) w += 0.42;
		else if (/[ il.,:;|'!()\[\]]/.test(ch)) w += 0.3;
		else if (/[A-Z]/.test(ch)) w += 0.66;
		else if (/[mwMW]/.test(ch)) w += 0.8;
		else if (/[→⇌×−+=]/.test(ch)) w += 0.62;
		else w += 0.55;
	}
	return w * size;
};

/** Straight arrow with a filled head from (x1,y1) to (x2,y2); `t` draws it in. */
export const Arrow = ({x1, y1, x2, y2, color, width = 3, t = 1, head = 10}: {x1: number; y1: number; x2: number; y2: number; color: string; width?: number; t?: number; head?: number}) => {
	if (t <= 0) return null;
	const ex = x1 + (x2 - x1) * t, ey = y1 + (y2 - y1) * t;
	const a = Math.atan2(y2 - y1, x2 - x1);
	const hx = ex - Math.cos(a) * head, hy = ey - Math.sin(a) * head;
	return (
		<g>
			<line x1={x1} y1={y1} x2={hx} y2={hy} stroke={color} strokeWidth={width} strokeLinecap="round" />
			<path d={`M ${ex} ${ey} L ${hx + Math.sin(a) * head * 0.6} ${hy - Math.cos(a) * head * 0.6} L ${hx - Math.sin(a) * head * 0.6} ${hy + Math.cos(a) * head * 0.6} Z`} fill={color} />
		</g>
	);
};

// ── Numbers ────────────────────────────────────────────────────────────────

const SUP: Record<string, string> = {'-': '⁻', '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹'};
export const sup = (s: string) => s.split('').map((c) => SUP[c] ?? c).join('');

/** 0.00134 → "1.3 × 10⁻³" (sig figs `sf`). Numbers in [0.01, 1000) print plainly. */
export const sci = (v: number, sf = 2, plainRange = true) => {
	if (v === 0) return '0';
	const e = Math.floor(Math.log10(Math.abs(v)));
	if (plainRange && e >= -2 && e < 3) return v.toPrecision(sf);
	const m = v / 10 ** e;
	return `${m.toFixed(sf - 1)} × 10${sup(String(e))}`;
};

export const KW = 1.0e-14;

/**
 * Exact [H⁺] of an aqueous mixture by charge balance (bisection on log[H⁺]):
 * [H⁺] + [M⁺ from strong base] + Σ[BH⁺] = [OH⁻] + [X⁻ from strong acid] + Σ[A⁻].
 * Concentrations in mol L⁻¹, already corrected for total volume.
 */
export const solvePH = ({
	strongAcid = 0, strongBase = 0, weakAcids = [], weakBases = [],
}: {strongAcid?: number; strongBase?: number; weakAcids?: {c: number; Ka: number}[]; weakBases?: {c: number; Kb: number}[]}) => {
	const f = (h: number) => {
		const oh = KW / h;
		const aMinus = weakAcids.reduce((s, a) => s + (a.c * a.Ka) / (a.Ka + h), 0);
		const bhPlus = weakBases.reduce((s, b) => s + (b.c * b.Kb * h) / (b.Kb * h + KW), 0);
		return h + strongBase + bhPlus - oh - strongAcid - aMinus;
	};
	let lo = -15.5, hi = 1.5; // log10[H⁺]
	for (let i = 0; i < 90; i++) {
		const mid = (lo + hi) / 2;
		if (f(10 ** mid) > 0) hi = mid; else lo = mid;
	}
	return -(lo + hi) / 2;
};

/** Universal-indicator-ish colour for a pH (red → orange → yellow → green → blue → purple). */
export const phColor = (pH: number) => {
	const stops: [number, string][] = [
		[0, '#d7263d'], [2, '#ee5a24'], [4, '#f5a623'], [6, '#e8d23a'], [7, '#6cbf4a'], [8, '#2fa37a'],
		[10, '#2d7fd1'], [12, '#4b4fb8'], [14, '#6a3d9a'],
	];
	const p = Math.max(0, Math.min(14, pH));
	for (let i = 1; i < stops.length; i++) {
		if (p <= stops[i][0]) {
			const [a, ca] = stops[i - 1], [b, cb] = stops[i];
			return mix(ca, cb, (p - a) / (b - a));
		}
	}
	return stops[stops.length - 1][1];
};

/** A labelled glass beaker standing at (cx, baseY); children draw inside the liquid. */
export const Beaker = ({
	cx, baseY, w, h, level = 0.72, liquid = 'rgba(120,190,235,0.28)', children,
}: {cx: number; baseY: number; w: number; h: number; level?: number; liquid?: string; children?: ReactNode}) => {
	const x0 = cx - w / 2, x1 = cx + w / 2, top = baseY - h;
	const lip = 8;
	const ly = baseY - h * level;
	return (
		<g>
			<ellipse cx={cx + 6} cy={baseY + 4} rx={w * 0.55} ry={9} fill="rgba(40,36,30,0.18)" />
			<path d={`M ${x0} ${ly} L ${x0} ${baseY - 10} Q ${x0} ${baseY} ${x0 + 10} ${baseY} L ${x1 - 10} ${baseY} Q ${x1} ${baseY} ${x1} ${baseY - 10} L ${x1} ${ly} Z`} fill={liquid} />
			<ellipse cx={cx} cy={ly} rx={w / 2} ry={6} fill={liquid} opacity={0.9} />
			{children}
			<path
				d={`M ${x0 - lip} ${top} Q ${x0} ${top} ${x0} ${top + lip} L ${x0} ${baseY - 10} Q ${x0} ${baseY} ${x0 + 10} ${baseY} L ${x1 - 10} ${baseY} Q ${x1} ${baseY} ${x1} ${baseY - 10} L ${x1} ${top + lip} Q ${x1} ${top} ${x1 + lip} ${top}`}
				fill="none"
				stroke="rgba(70,90,110,0.55)"
				strokeWidth={3}
				strokeLinejoin="round"
			/>
			<rect x={x0 + 8} y={top + 16} width={7} height={h - 34} rx={3.5} fill="#ffffff" opacity={0.45} />
		</g>
	);
};

/** Deterministic pseudo-random in [0, 1) from an integer seed. */
export const hash01 = (n: number) => {
	const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
	return s - Math.floor(s);
};

